import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatSidebar.css";

const ChatSidebar = ({ onSelectConversation, refreshTrigger }) => {
  const [conversations, setConversations] = useState([]);
  const user = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    const fetchConversations = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/conversations/${user.userId}`);
        setConversations(res.data);
      } catch (err) {
        console.error("Error fetching conversations:", err);
      }
    };

    fetchConversations();
  }, [refreshTrigger, user.userId]);

  return (
    <div className="chat-sidebar">
      <h3>Messages</h3>
      {conversations.length === 0 ? (
        <p>No conversations found.</p>
      ) : (
        <ul>
          {conversations.map((conv) => {
            const otherUsername = conv.participantUsernames.find(name => name !== user.username);
            return (
              <li key={conv._id} onClick={() => onSelectConversation(conv)}>
                <strong>{otherUsername}</strong>
                <p className="last-msg">{conv.lastMessage}</p>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
};

export default ChatSidebar;
